using System;
using System.Drawing;
using System.Windows.Forms;

public ExampleForm()
{
    Text = "OpenFileDialog example";
    ClientSize = new Size(420, 120);
    InitializeComponents();
}

btnOpen = new Button();
btnOpen.Text = "Open...";
btnOpen.Location = new Point(20, 20);
btnOpen.Click += BtnOpen_Click;

lblFile = new Label();
lblFile.AutoSize = true;
lblFile.Location = new Point(20, 60);
lblFile.Text = "No file chosen";

private void BtnOpen_Click(object sender, EventArgs e)
{
    using (OpenFileDialog ofd = new OpenFileDialog())
    {
        ofd.Title = "Choose a text file";
        ofd.Filter = "Text files (*.txt)|*.txt|All files (*.*)|*.*";
        ofd.InitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);

        if (ofd.ShowDialog() == DialogResult.OK)
        {
            lblFile.Text = ofd.FileName;
        }
    }
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

using System;
using System.Drawing;
using System.IO;
using System.Windows.Forms;

public ExampleForm()
{
    Text = "SaveFileDialog example";
    ClientSize = new Size(380, 200);
    InitializeComponents();
}

txtContent = new TextBox();
txtContent.Multiline = true;
txtContent.Location = new Point(20, 20);
txtContent.Size = new Size(320, 100);

btnSave = new Button();
btnSave.Text = "Save as...";
btnSave.Location = new Point(20, 130);
btnSave.Click += BtnSave_Click;

private void BtnSave_Click(object sender, EventArgs e)
{
    using (SaveFileDialog sfd = new SaveFileDialog())
    {
        sfd.Filter = "Text file (*.txt)|*.txt";
        sfd.DefaultExt = "txt";
        sfd.FileName = "notes.txt";

        if (sfd.ShowDialog() == DialogResult.OK)
        {
            File.WriteAllText(sfd.FileName, txtContent.Text);
        }
    }
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

