using System;
using System.Drawing;
using System.Windows.Forms;

public ExampleForm()
{
    Text = "FontDialog example";
    ClientSize = new Size(320, 120);
    InitializeComponents();
}

lblSample = new Label();
lblSample.AutoSize = true;
lblSample.Text = "The quick brown fox";
lblSample.Location = new Point(20, 60);

btnFont = new Button();
btnFont.Text = "Choose font...";
btnFont.Size = new Size(120, 30);
btnFont.Location = new Point(20, 20);
btnFont.Click += BtnFont_Click;

private void BtnFont_Click(object sender, EventArgs e)
{
    using (FontDialog fd = new FontDialog())
    {
        fd.Font = lblSample.Font;
        fd.ShowColor = true;
        fd.Color = lblSample.ForeColor;

        if (fd.ShowDialog() == DialogResult.OK)
        {
            lblSample.Font = fd.Font;
            lblSample.ForeColor = fd.Color;
        }
    }
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}
